<?php
$e = static fn($value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$state = (string)($waitlistStatus['status'] ?? 'waiting');
$label = match ($state) { 'waiting' => 'You are in the queue', 'seated' => 'Your table is ready', 'left' => 'You have left the waiting list', 'cancelled' => 'Waiting-list entry cancelled', default => 'Waiting-list status' };
$errorMessage = trim((string)($error ?? ''));
$description = match ($state) { 'waiting' => 'Keep this page open to check your queue position. Please stay near the restaurant.', 'seated' => 'Please check in with a team member to be shown to your table.', 'left' => 'This entry is no longer active. Please speak to staff if you still need a table.', 'cancelled' => 'This entry is no longer active. Please speak to staff if you still need a table.', default => '' };
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f3f6fb"><?php if ($state==='waiting'): ?><meta http-equiv="refresh" content="15"><?php endif; ?><title>Queue Status · <?= $e($waitlistStatus['restaurant_name']) ?></title>
<style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:22px;background:#f3f6fb;color:#182338;font:16px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{width:min(100%,480px)}.brand{text-align:center;margin-bottom:22px}.brand h1{font-size:1.4rem;margin:0}.card{background:white;border:1px solid #e1e8f1;border-radius:22px;padding:28px;box-shadow:0 14px 40px rgba(28,49,82,.08);text-align:center}.badge{display:inline-block;border-radius:999px;padding:6px 11px;background:#e6f7ee;color:#087443;font-size:.82rem;font-weight:800}.number{font-size:4rem;font-weight:850;line-height:1.1;letter-spacing:-.06em;margin:20px 0 8px;color:#1769e8}.sub{color:#66758c;margin:0}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:24px 0}.metric{border:1px solid #e1e8f1;border-radius:14px;padding:14px}.metric small{display:block;color:#66758c}.metric strong{font-size:1.2rem}.note{border-top:1px solid #e9eef5;padding-top:18px;color:#66758c;font-size:.9rem}.cancel-form{margin-top:18px}.cancel-btn{width:100%;border:1px solid #d92d20;background:#fff;color:#b42318;border-radius:12px;padding:13px 16px;font:inherit;font-weight:750;cursor:pointer}.cancel-btn:hover{background:#fff1f0}.error{margin:0 0 16px;padding:11px 13px;border-radius:10px;background:#fff1f0;color:#b42318;font-size:.9rem;text-align:left}.footer{text-align:center;color:#66758c;font-size:.78rem;margin-top:18px}
</style></head><body><main class="wrap"><header class="brand"><h1><?= $e($waitlistStatus['restaurant_name']) ?></h1><p class="sub">Waiting list status</p></header><section class="card"><?php if ($errorMessage !== ''): ?><p class="error"><?= $e($errorMessage) ?></p><?php endif; ?><span class="badge"><?= $e($label) ?></span>
<?php if ($state === 'waiting'): ?><div class="number">#<?= (int)$waitlistStatus['position'] ?></div><p class="sub">Your current queue position</p><?php else: ?><div style="font-size:3rem;margin:18px 0;color:#1769e8">✓</div><?php endif; ?>
<div class="metrics"><div class="metric"><small>Name</small><strong><?= $e($waitlistStatus['customer_name']) ?></strong></div><div class="metric"><small>Party size</small><strong><?= (int)$waitlistStatus['party_size'] ?> <?= (int)$waitlistStatus['party_size']===1?'guest':'guests' ?></strong></div>
<?php if ($state === 'waiting'): ?><div class="metric" style="grid-column:1/-1"><small>Estimated wait</small><strong><?= (int)$waitlistStatus['estimated_wait_minutes'] > 0 ? (int)$waitlistStatus['estimated_wait_minutes'].' minutes' : 'We will update you shortly' ?></strong></div><?php endif; ?></div>
<p class="note"><?= $e($description) ?><?php if ($state==='waiting'): ?><br><br><small>This page refreshes automatically every 15 seconds.</small><?php endif; ?></p><?php if ($state === 'waiting'): ?><form class="cancel-form" method="post" action="/waitlist/<?= $e($linkToken) ?>/status/<?= $e($trackingToken) ?>/cancel" onsubmit="return confirm('Are you sure you want to cancel your place in the queue?');"><input type="hidden" name="_csrf_token" value="<?= $e($csrf_token) ?>"><button class="cancel-btn" type="submit">Cancel my place in the queue</button></form><?php endif; ?></section><p class="footer">Powered by ServeFlow POS</p></main></body></html>